INSERT INTO purpose VALUES('surface-agentic','connection::Connection','struct','Holds one client''s place, so the messages it sends are answered over the shared workspace and the notifications its subscriptions owe it are sent when a document changes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','connection::LEGACY','constant','Names the handshake-based revisions an `initialize` may name, so a legacy client''s version is answered.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','connection::MODERN','constant','Names the protocol revision that carries its version in every request, so a modern client''s version is answered.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','connection::Refusal','enum','Names why a message is refused, so the refusal''s kind is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','face::Relayed','enum','Names how a relayed model session ended, so `gandr mcp` either exits or hands the session to the selected build.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','face::relay','function','Carries a client''s standard streams to the hub a line at a time, so `gandr mcp` reaches the hub as `gandr lsp` does and follows a toolchain switch.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','face::serve','function','Serves the Model Context Protocol on a connection''s buffered stream, so the hub''s line face answers a model''s messages.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','rap::Announced','struct','Holds the address file that `gandr serve` wrote, so the file goes when the hub stops.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','rap::Announcement','struct','Names the file beside the hub''s socket that holds the URL of the toolset''s manifest, so a runtime that did not start the hub finds the toolset and a second hub of the workspace stops.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','rap::Toolset','struct','Serves the Reactive Agent Protocol''s manifest and invoke endpoint beside the hub''s socket, so an agent runtime calls the hub''s tools and hears each answer by a callback.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','rap::deliver::Policy','struct','States when the toolset tries a failed callback again and how often, so a runtime that fails for a time still receives each result and each new state.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','rap::deliver::Retries','struct','Counts the attempts of a delivery after the first.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','rap::jobs::JobStream','struct','One stream of a job of the hub: the text that a verb writes, kept until the job ends, and refused once the job is retired.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','rap::jobs::Verbs','trait','Walks the paths of a `check` or a `test` job on the hub''s pool as the command line walks them, so the toolset answers a long operation with the lines that the verb prints.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-agentic','tools::ToolRefusal','struct','Names why a tool call produced no result, so the refusal''s text is read.',NULL,'fits','sound',NULL);
